function IdolLive3D_TextDebug:Start()
    KTool.SetActive(self.controller.gameObject, true);   

    self.isShow = false
    -- local params = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    -- if isNotNull(params) then 
    --     self.isShow  = LuaParametersReader.Read( params, "isShow", LuaParametersType.Bool )
    -- end
    
    self.canvas = KTool.GetComponent(self.canvasGroup.gameObject, typeof(Canvas))
    if isNotNull(self.canvas) then 
        -- self.canvas.enabled = checkBool( self.isShow) 
        -- IdolLive3D_Utils.SetCanvasGroupAlpha(self.canvasGroup, self.isShow and 1.0 or 0.0 )
        self:_Show( self.isShow )
    else 
        printError( "没绑 Canvas 组件" )
        KTool.SetActive( self.canvasGroup.gameObject, false )
    end 

    self.EventShowDebugUI  = Events.AddListener(IdolLive3D_States.EventShowDebugUI, function(isShow_)
        -- 暂时没用到 isShow_ 这个值:
        self.isShow = not self.isShow
        self:_Show( self.isShow )
    end)

    assert( self.text1 and self.text2 and self.text3 )
end



function IdolLive3D_TextDebug:OnDestroy()
    if self.EventShowDebugUI then
        Events.RemoveListener(IdolLive3D_States.EventShowDebugUI, self.EventShowDebugUI)
    end


    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


-- ===============================================================



function IdolLive3D_TextDebug:SetText( idx_, log_ )
    if idx_ == 1 then
        self.text1.text = "Yaw:  " .. log_
    elseif idx_ == 2 then
        self.text2.text = "Pitch: " .. log_
    elseif idx_ == 3 then
        self.text3.text = "Zoom:  " .. log_
    end
end



function IdolLive3D_TextDebug:_Show( isShow_ )
    if isShow_ == true then 
        self.canvas.enabled = true
        IdolLive3D_Utils.SetCanvasGroupAlpha(self.canvasGroup, 1.0 )
    else 
        self.canvas.enabled = false
        IdolLive3D_Utils.SetCanvasGroupAlpha(self.canvasGroup, 0.0 )
    end 
end




return IdolLive3D_TextDebug
